// Keep successful runs KEEP_DAYS; keep anything that did NOT succeed far longer.
//
// Two-tier on purpose. Pruning at 3 days destroyed the evidence for the 2-3 Sept
// outages before anyone could study them, and later made it impossible to tell
// whether an old speed measurement had been taken under concurrent load. SQLite
// pressure - the reason the window was short - was ruled out: no lock or disk
// errors, contiguous execution ids, no latency creep before either stall, and the
// heaviest hour of those three days ran clean.
//
// Failures are rare and tiny in volume, and they are the ones worth reading, so
// they get a much longer window than the successes that make up the bulk.
//
// Capped per run so a backlog drains over several nights instead of landing
// thousands of writes on SQLite at once - the deletes contend with the same
// file a booking writes to.
const KEEP_DAYS        = 7;    // status === success
const KEEP_DAYS_FAILED = 30;   // error, crashed, canceled - keep for diagnosis
const MAX_PER_RUN      = 800;

// Anything still in flight is never touched, whatever its age.
const IN_FLIGHT = ['running', 'waiting', 'new'];

const now       = Date.now();
const cutoffOk  = now - KEEP_DAYS * 24 * 60 * 60 * 1000;
const cutoffBad = now - KEEP_DAYS_FAILED * 24 * 60 * 60 * 1000;
const seen = {};
const out  = [];

// The List node paginates, so input arrives either as one item per page (each
// carrying a `data` array) or as one item per execution, depending on how n8n
// splits the response. Handle both rather than assuming.
for (const item of $input.all()) {
  const j = (item && item.json) || {};
  const rows = Array.isArray(j.data) ? j.data : [j];
  for (const e of rows) {
    if (!e || !e.id || seen[e.id]) continue;

    const status = String(e.status || '').toLowerCase();
    if (IN_FLIGHT.indexOf(status) !== -1) continue;

    // Unknown/blank status is treated as a failure - keep it longer rather than
    // delete something we cannot classify.
    const cutoff = status === 'success' ? cutoffOk : cutoffBad;

    const started = Date.parse(e.startedAt || e.createdAt || '');
    if (!started || started >= cutoff) continue;

    seen[e.id] = 1;
    out.push({ json: { id: e.id, startedAt: e.startedAt, status: status } });
    if (out.length >= MAX_PER_RUN) return out;
  }
}
return out;

const items = $input.all();
const ok = items.filter(i => !(i.json && i.json.error)).length;
return [{ json: { pruned: ok, attempted: items.length, at: new Date().toISOString() } }];

